solution.solution.cpp:
#include <algorithm>
#include <vector>

struct Vector2 { float x, y; };
struct Rectangle { float x, y, width, height; };
struct Hits { bool left{ false }, right{ false }, ceiling{ false }, ground{ false }; };

namespace
{
    bool overlap(const Rectangle& a, const Rectangle& b)
    {
        return a.x < b.x + b.width && b.x < a.x + a.width && a.y < b.y + b.height && b.y < a.y + a.height;
    }
    float dot(Vector2 a, Vector2 b) { return a.x * b.x + a.y * b.y; }
}

Hits moveAndSlide(Rectangle& box, Vector2& vel, float dt, const std::vector<Rectangle>& walls)
{
    Hits h;
    box.x += vel.x * dt;
    float stopX{ box.x };
    for (const Rectangle& w : walls)
    {
        if (!overlap(box, w)) continue;
        if (vel.x > 0) { stopX = std::min(stopX, w.x - box.width); h.right = true; }
        else if (vel.x < 0) { stopX = std::max(stopX, w.x + w.width); h.left = true; }
    }
    if (h.left || h.right) { box.x = stopX; vel.x = 0; }

    box.y += vel.y * dt;
    float stopY{ box.y };
    for (const Rectangle& w : walls)
    {
        if (!overlap(box, w)) continue;
        if (vel.y > 0) { stopY = std::min(stopY, w.y - box.height); h.ground = true; }
        else if (vel.y < 0) { stopY = std::max(stopY, w.y + w.height); h.ceiling = true; }
    }
    if (h.ground || h.ceiling) { box.y = stopY; vel.y = 0; }
    return h;
}

Vector2 slide(Vector2 v, Vector2 n)
{
    const float d{ dot(v, n) };
    return { v.x - d * n.x, v.y - d * n.y };
}

Vector2 bounce(Vector2 v, Vector2 n, float bounciness)
{
    const float d{ dot(v, n) };
    const Vector2 along{ d * n.x, d * n.y };
    const Vector2 rest{ v.x - along.x, v.y - along.y };
    return { rest.x - along.x * bounciness, rest.y - along.y * bounciness };
}

unitTests:
TEST("blocked on the right, still falls") {
    Rectangle box{ 0, 0, 10, 10 }; Vector2 v{ 100, 50 };
    const Hits h = moveAndSlide(box, v, 0.1f, { { 15, -100, 10, 300 } });
    CHECK(h.right); CHECK(!h.ground); CHECK_NEAR(box.x, 5.0, 1e-4); CHECK_NEAR(box.y, 5.0, 1e-4); CHECK_NEAR(v.x, 0.0, 1e-6); CHECK_NEAR(v.y, 50.0, 1e-6);
}
TEST("landing") { Rectangle box{ 0, 0, 10, 10 }; Vector2 v{ 0, 200 }; const Hits h = moveAndSlide(box, v, 0.1f, { { -50, 25, 100, 10 } }); CHECK(h.ground); CHECK_NEAR(box.y, 15.0, 1e-4); CHECK_NEAR(v.y, 0.0, 1e-6); }
TEST("ceiling and left") {
    Rectangle box{ 50, 50, 10, 10 }; Vector2 v{ -100, -100 };
    const Hits h = moveAndSlide(box, v, 0.1f, { { 0, 0, 45, 200 }, { 0, 0, 200, 45 } });
    CHECK(h.left); CHECK(h.ceiling); CHECK_NEAR(box.x, 45.0, 1e-4); CHECK_NEAR(box.y, 45.0, 1e-4);
}
TEST("nearest stop wins") { Rectangle box{ 0, 0, 10, 10 }; Vector2 v{ 200, 0 }; moveAndSlide(box, v, 0.1f, { { 25, 0, 10, 10 }, { 15, 0, 10, 10 } }); CHECK_NEAR(box.x, 5.0, 1e-4); }
TEST("walking along a floor of tiles") {
    Rectangle box{ 0, 20, 10, 10 }; Vector2 v{ 100, 0 };
    const Hits h = moveAndSlide(box, v, 0.5f, { { 0, 30, 32, 32 }, { 32, 30, 32, 32 }, { 64, 30, 32, 32 } });
    CHECK(!h.right); CHECK_NEAR(box.x, 50.0, 1e-4); CHECK_NEAR(v.x, 100.0, 1e-6);
}
TEST("slide and bounce") {
    const Vector2 s = slide({ 3, 4 }, { 0, -1 }); CHECK_NEAR(s.x, 3.0, 1e-5); CHECK_NEAR(s.y, 0.0, 1e-5);
    const Vector2 b = bounce({ 3, 4 }, { 0, -1 }, 0.5f); CHECK_NEAR(b.x, 3.0, 1e-5); CHECK_NEAR(b.y, -2.0, 1e-5);
    const Vector2 c = bounce({ 2, 0 }, { -1, 0 }, 1.0f); CHECK_NEAR(c.x, -2.0, 1e-5);
}

